1	// The methods under comparison, each behind one of two seams: a retriever (a distance
2	// between claims, and the nearest ones to a claim) and a pair judge (a relation between
3	// two claims). The comparison scores the seams, never the models — which is what lets it
4	// run today on the one method that needs no model, and score a real one by wiring it here
5	// once it is reachable (#34).
6	import type { Embedder } from '../../src/backend/ingestion/ports.ts';
7	import { indexTerms } from '../../src/shared/text.ts';
8	import { syntacticSemanticJaccard, type Decomposed, type Similarity } from './measure.ts';
9	import type { Claim, Relation } from './pairs.ts';
10	
11	/** What a method spent. Characters rather than tokens: tokens are a model's own count. */
12	export type Cost = { calls: number; characters: number };
13	
14	export type Neighbour = { id: string; distance: number };
15	
16	export type Retriever = {
17	  readonly name: string;
18	  readonly cost: Cost;
19	  /** Sees every claim once before any distance is asked for. */
20	  index(claims: Claim[]): Promise<void>;
21	  /** Between two indexed claims; 0 is identical, 1 is nothing in common. */
22	  distance(a: string, b: string): number;
23	  /** The nearest indexed claims to one of them, itself excluded, nearest first, ties by id. */
24	  nearest(claimId: string, limit: number): Neighbour[];
25	};
26	
27	export type Judgment = {
28	  relation: Relation;
29	  /** The judge's own confidence or similarity, 0..1 — reported, never compared across judges. */
30	  score: number;
31	  /** Whatever lets a reader check the judgment: matched clauses, class probabilities, a reason. */
32	  trail?: unknown;
33	};
34	
35	export type PairJudge = {
36	  readonly name: string;
37	  readonly cost: Cost;
38	  judge(a: Claim, b: Claim): Promise<Judgment>;
39	};
40	
41	/**
42	 * Exact nearest-neighbour over a distance between stored representations. Brute force on
43	 * purpose: the comparison measures the *distance*, and an approximate index would mix its
44	 * own recall into the number. Production uses Vectorize; a benchmark set fits in memory.
45	 */
46	function exactRetriever<Stored>(
47	  name: string,
48	  cost: Cost,
49	  represent: (claim: Claim) => Promise<Stored>,
50	  distanceOf: (x: Stored, y: Stored) => number,
51	): Retriever {
52	  const stored = new Map<string, Stored>();
53	  const of = (id: string): Stored => {
54	    const representation = stored.get(id);
55	    if (representation === undefined) throw new Error(`${name}: claim ${id} was never indexed`);
56	    return representation;
57	  };
58	  return {
59	    name,
60	    cost,
61	    async index(claims) {
62	      for (const claim of claims) stored.set(claim.id, await represent(claim));
63	    },
64	    distance: (a, b) => distanceOf(of(a), of(b)),
65	    nearest(claimId, limit) {
66	      const self = of(claimId);
67	      return [...stored]
68	        .filter(([id]) => id !== claimId)
69	        .map(([id, other]) => ({ id, distance: distanceOf(self, other) }))
70	        .sort((x, y) => x.distance - y.distance || x.id.localeCompare(y.id))
71	        .slice(0, limit);
72	    },
73	  };
74	}
75	
76	/** 0 for the same direction, 1 for orthogonal or empty. */
77	export function cosineDistance(x: number[], y: number[]): number {
78	  let dot = 0;
79	  let normX = 0;
80	  let normY = 0;
81	  for (let i = 0; i < Math.max(x.length, y.length); i++) {
82	    const a = x[i] ?? 0;
83	    const b = y[i] ?? 0;
84	    dot += a * b;
85	    normX += a * a;
86	    normY += b * b;
87	  }
88	  if (!normX || !normY) return 1;
89	  return 1 - dot / Math.sqrt(normX * normY);
90	}
91	
92	// ---- lexical: the baseline that runs today ----------------------------------------------
93	
94	const termSet = (text: string): Set<string> => new Set(indexTerms(text));
95	
96	/** 1 − Jaccard over two folded term sets. */
97	function jaccardDistance(x: Set<string>, y: Set<string>): number {
98	  if (x.size === 0 && y.size === 0) return 0;
99	  let shared = 0;
100	  for (const term of x) if (y.has(term)) shared += 1;
101	  return 1 - shared / (x.size + y.size - shared);
102	}
103	
104	/** 1 − Jaccard over the folded terms the search index already writes. */
105	export const lexicalDistance = (a: string, b: string): number => jaccardDistance(termSet(a), termSet(b));
106	
107	/**
108	 * Hebrew-aware token overlap — what the corpus's search does, as a retriever. It is the
109	 * floor every model has to clear, and the one method with no cost column.
110	 */
111	export function lexicalRetriever(): Retriever {
112	  return exactRetriever('lexical', { calls: 0, characters: 0 }, async (claim) => termSet(claim.text), jaccardDistance);
113	}
114	
115	/**
116	 * The same overlap read as a relation. It can say "the same words" and "some of the same
117	 * words" and nothing else: its contradiction recall is zero by construction, which is the
118	 * number that shows why a judge has to read meaning.
119	 */
120	export function lexicalJudge(thresholds = { equivalent: 0.8, sameSubject: 0.25 }): PairJudge {
121	  return {
122	    name: 'lexical',
123	    cost: { calls: 0, characters: 0 },
124	    async judge(a, b) {
125	      const overlap = 1 - lexicalDistance(a.text, b.text);
126	      const relation: Relation =
127	        overlap >= thresholds.equivalent ? 'equivalent' : overlap >= thresholds.sameSubject ? 'same-subject' : 'unrelated';
128	      return { relation, score: overlap };
129	    },
130	  };
131	}
132	
133	// ---- model-backed: the seams a real method is wired into ------------------------------
134	
135	/** Cosine distance over an `Embedder` — the ingestion port, so a Worker-reachable model plugs in unchanged. */
136	export function embeddingRetriever(embedder: Embedder): Retriever {
137	  const cost: Cost = { calls: 0, characters: 0 };
138	  return exactRetriever(
139	    `embedding:${embedder.modelVersion}`,
140	    cost,
141	    async (claim) => {
142	      cost.calls += 1;
143	      cost.characters += claim.text.length;
144	      return embedder.embed(claim.text);
145	    },
146	    cosineDistance,
147	  );
148	}
149	
150	/**
151	 * A model that judges a pair: an NLI cross-encoder, an LLM prompt, or anything else that
152	 * takes two texts and returns a relation. This is the shape a pair-judging port would take
153	 * beside `StanceModel` in the ingestion ports, once the comparison has earned it a place.
154	 */
155	export type PairModel = {
156	  readonly modelVersion: string;
157	  readonly promptVersion: string;
158	  judge(a: string, b: string): Promise<Judgment>;
159	};
160	
161	export function modelJudge(model: PairModel, kind = 'model'): PairJudge {
162	  const cost: Cost = { calls: 0, characters: 0 };
163	  return {
164	    name: `${kind}:${model.modelVersion}/${model.promptVersion}`,
165	    cost,
166	    async judge(a, b) {
167	      cost.calls += 1;
168	      cost.characters += a.text.length + b.text.length;
169	      return model.judge(a.text, b.text);
170	    },
171	  };
172	}
173	
174	/**
175	 * What the paper's method needs from a model: the decomposition prompts and the
176	 * clause-level relation. `relate` is three-way rather than the paper's yes/no because a
177	 * product looking for inconsistency needs the third answer — the paper's measure scores an
178	 * argument and its negation exactly as it scores two unrelated ones.
179	 */
180	export type ClauseModel = {
181	  readonly modelVersion: string;
182	  readonly promptVersion: string;
183	  decompose(text: string): Promise<Decomposed>;
184	  relate(p: string, q: string): Promise<'entails' | 'contradicts' | 'neutral'>;
185	};
186	
187	/**
188	 * The paper's measure as a judge. Equivalent when the measure is 1; contradicts when any
189	 * two consequences contradict; entails when every consequence class is shared; same-subject
190	 * on any overlap at all; unrelated on none. The mapping from a similarity to a relation is
191	 * this harness's, not the paper's — the paper reports similarity only.
192	 */
193	export function logicalJudge(model: ClauseModel, sigma = 0.5): PairJudge {
194	  const cost: Cost = { calls: 0, characters: 0 };
195	  const decompositions = new Map<string, Promise<Decomposed>>();
196	  const decompose = (text: string): Promise<Decomposed> => {
197	    let pending = decompositions.get(text);
198	    if (!pending) {
199	      cost.calls += 1;
200	      cost.characters += text.length;
201	      pending = model.decompose(text);
202	      decompositions.set(text, pending);
203	    }
204	    return pending;
205	  };
206	  return {
207	    name: `logical:${model.modelVersion}/${model.promptVersion}`,
208	    cost,
209	    async judge(a, b) {
210	      const [left, right] = await Promise.all([decompose(a.text), decompose(b.text)]);
211	      const relations = new Map<string, 'entails' | 'contradicts' | 'neutral'>();
212	      const relate = async (p: string, q: string) => {
213	        const key = `${p}�${q}`;
214	        let relation = relations.get(key);
215	        if (!relation) {
216	          cost.calls += 1;
217	          cost.characters += p.length + q.length;
218	          relation = await model.relate(p, q);
219	          relations.set(key, relation);
220	        }
221	        return relation;
222	      };
223	      const equivalent = async (p: string, q: string) => (await relate(p, q)) === 'entails' && (await relate(q, p)) === 'entails';
224	      const measured: Similarity = await syntacticSemanticJaccard(left, right, equivalent, sigma);
225	
226	      let contradicted = false;
227	      for (const p of left.consequences) {
228	        for (const q of right.consequences) {
229	          if ((await relate(p, q)) === 'contradicts') contradicted = true;
230	        }
231	      }
232	      const covered = measured.consequences.distinct > 0 && measured.consequences.shared === measured.consequences.distinct;
233	      const relation: Relation = contradicted
234	        ? 'contradicts'
235	        : measured.similarity === 1
236	          ? 'equivalent'
237	          : covered
238	            ? 'entails'
239	            : measured.similarity > 0
240	              ? 'same-subject'
241	              : 'unrelated';
242	      return {
243	        relation,
244	        score: measured.similarity,
245	        trail: { premises: measured.premises.classes, consequences: measured.consequences.classes },
246	      };
247	    },
248	  };
249	}
