1	// What the harness itself is proven by, so a number it reports later is a number about the
2	// model and not about the arithmetic: the metrics on hand-computable inputs, the paper's
3	// measure on the paper's own worked example, and the whole protocol on a set small enough
4	// to check by hand.
5	import assert from 'node:assert/strict';
6	import test from 'node:test';
7	import type { Embedder } from '../../src/backend/ingestion/ports.ts';
8	import { compare, renderReport } from './compare.ts';
9	import { syntacticSemanticJaccard, type Equivalent } from './measure.ts';
10	import { recallAtK, reciprocalRank, scorecard, separation } from './metrics.ts';
11	import { embeddingRetriever, lexicalDistance, lexicalJudge, lexicalRetriever, logicalJudge, type ClauseModel } from './methods.ts';
12	import { claimsOf, parsePairs, readPairs, type LabelledPair } from './pairs.ts';
13	import { SAMPLE_PAIRS, resolveMethods } from './run.ts';
14	
15	test('recall@k and reciprocal rank read a ranking the obvious way', () => {
16	  const relevant = new Set(['b', 'd']);
17	  assert.equal(recallAtK(['a', 'b', 'c', 'd'], relevant, 2), 0.5);
18	  assert.equal(recallAtK(['a', 'b', 'c', 'd'], relevant, 4), 1);
19	  assert.equal(recallAtK(['a', 'c'], relevant, 2), 0);
20	  assert.equal(reciprocalRank(['a', 'b', 'c', 'd'], relevant), 0.5);
21	  assert.equal(reciprocalRank(['a', 'c'], relevant), 0);
22	  assert.throws(() => recallAtK(['a'], new Set(), 1), /undefined/);
23	});
24	
25	test('separation is the probability a near pair scores below a far one, ties counting half', () => {
26	  assert.equal(separation([0.1, 0.2], [0.8, 0.9]), 1);
27	  assert.equal(separation([0.8, 0.9], [0.1, 0.2]), 0);
28	  assert.equal(separation([0.5], [0.5]), 0.5);
29	  // Three of four comparisons the right way round.
30	  assert.equal(separation([0.1, 0.7], [0.5, 0.9]), 0.75);
31	});
32	
33	test('the scorecard counts precision and recall per relation and reads contradiction recall on its own', () => {
34	  const card = scorecard(
35	    ['contradicts', 'contradicts', 'equivalent', 'unrelated'],
36	    ['contradicts', 'unrelated', 'equivalent', 'unrelated'],
37	  );
38	  assert.equal(card.perRelation.contradicts.recall, 0.5);
39	  assert.equal(card.perRelation.contradicts.precision, 1);
40	  assert.equal(card.perRelation.unrelated.precision, 0.5);
41	  assert.equal(card.perRelation.equivalent.f1, 1);
42	  // Relations with no gold pair are left out of the macro average rather than dragging it to zero.
43	  assert.equal(card.perRelation.entails.support, 0);
44	  assert.equal(card.macroF1, (2 / 3 + 1 + 2 / 3) / 3);
45	  assert.equal(card.contradictionRecall, 0.5);
46	});
47	
48	test("the paper's worked example: one shared premise class of two, equivalent conclusions, sigma one half gives 0.75", async () => {
49	  // Figure 4 of arXiv 2608.15325: argument 77 has premises p1, p2 and conclusion c; argument
50	  // 4612 has premises q1, q2 and conclusion d. p2 is mutually entailed with both q1 and q2,
51	  // p1 with neither; c and d are mutually entailed.
52	  const equivalences = new Set(['p2|q1', 'p2|q2', 'c|d']);
53	  const equivalent: Equivalent = async (x, y) => equivalences.has(`${x}|${y}`) || equivalences.has(`${y}|${x}`);
54	  const result = await syntacticSemanticJaccard(
55	    { premises: ['p1', 'p2'], consequences: ['c'] },
56	    { premises: ['q1', 'q2'], consequences: ['d'] },
57	    equivalent,
58	  );
59	  assert.equal(result.similarity, 0.75);
60	  assert.deepEqual({ shared: result.premises.shared, distinct: result.premises.distinct }, { shared: 1, distinct: 2 });
61	  assert.deepEqual({ shared: result.consequences.shared, distinct: result.consequences.distinct }, { shared: 1, distinct: 1 });
62	});
63	
64	test("the paper's Figure 3: the same number of mutual entailments scores a half when they cover half the classes and one when they cover all", async () => {
65	  const premisesOnly = async (pairs: string[]) => {
66	    const set = new Set(pairs);
67	    const equivalent: Equivalent = async (x, y) => set.has(`${x}|${y}`);
68	    // Empty consequence sets on both sides contribute a full second half, so read the premise half alone.
69	    const result = await syntacticSemanticJaccard({ premises: ['p1', 'p2'], consequences: [] }, { premises: ['q1', 'q2'], consequences: [] }, equivalent);
70	    return result.similarity - 0.5;
71	  };
72	  assert.equal(await premisesOnly(['p1|q1', 'p1|q2']), 0.25);
73	  assert.equal(await premisesOnly(['p1|q1', 'p2|q2']), 0.5);
74	});
75	
76	test('the measure is one exactly for equivalent arguments and zero for disjoint ones', async () => {
77	  const same: Equivalent = async (x, y) => x === y;
78	  const alike = await syntacticSemanticJaccard({ premises: ['p'], consequences: ['c'] }, { premises: ['p'], consequences: ['c'] }, same);
79	  const apart = await syntacticSemanticJaccard({ premises: ['p'], consequences: ['c'] }, { premises: ['q'], consequences: ['d'] }, same);
80	  assert.equal(alike.similarity, 1);
81	  assert.equal(apart.similarity, 0);
82	  await assert.rejects(syntacticSemanticJaccard({ premises: [], consequences: [] }, { premises: [], consequences: [] }, same, 1), /sigma/);
83	});
84	
85	test('lexical distance folds Hebrew the way the search index does', () => {
86	  // A clitic on the front leaves the stem shared: the two are near, though the surface tokens differ.
87	  assert.ok(lexicalDistance('כנסת', 'בכנסת') < 0.5);
88	  assert.equal(lexicalDistance('ירושלים', 'ירושלימ'), 0);
89	  assert.ok(lexicalDistance('תקציב החינוך יגדל', 'תקציב החינוך יקוצץ') < 0.5);
90	  assert.equal(lexicalDistance('רכבת', 'חינוך'), 1);
91	});
92	
93	test('a pair set is refused at the door when a record does not say what it claims', () => {
94	  const good = '{"id":"p1","a":{"id":"a","utteranceId":"u","text":"x"},"b":{"id":"b","utteranceId":"u","text":"y"},"relation":"unrelated"}';
95	  assert.equal(parsePairs(good).length, 1);
96	  assert.throws(() => parsePairs(good.replace('"unrelated"', '"similar"'), 'set'), /set:1: relation must be one of/);
97	  assert.throws(() => parsePairs(`${good}\n${good}`), /:2: pair id p1 appears twice/);
98	  assert.throws(() => parsePairs(good.replace('"id":"b"', '"id":"a"')), /two different claims/);
99	  assert.throws(() => parsePairs('not json'), /:1: not JSON/);
100	  const twoTexts = `${good}\n${good.replace('"id":"p1"', '"id":"p2"').replace('"text":"y"', '"text":"z"')}`;
101	  assert.throws(() => claimsOf(parsePairs(twoTexts)), /claim b has two texts/);
102	});
103	
104	/** Four claims, hand-checkable: two about trains, two about schools; one contradiction in each subject. */
105	const TINY: LabelledPair[] = parsePairs(
106	  [
107	    '{"id":"t1","a":{"id":"a","utteranceId":"u","text":"הרכבת תיפתח בינואר"},"b":{"id":"b","utteranceId":"u","text":"הרכבת לא תיפתח בינואר"},"relation":"contradicts"}',
108	    '{"id":"t2","a":{"id":"c","utteranceId":"u","text":"תקציב החינוך יגדל"},"b":{"id":"d","utteranceId":"u","text":"תקציב החינוך יקוצץ"},"relation":"contradicts"}',
109	    '{"id":"t3","a":{"id":"a","utteranceId":"u","text":"הרכבת תיפתח בינואר"},"b":{"id":"c","utteranceId":"u","text":"תקציב החינוך יגדל"},"relation":"unrelated"}',
110	    '{"id":"t4","a":{"id":"b","utteranceId":"u","text":"הרכבת לא תיפתח בינואר"},"b":{"id":"d","utteranceId":"u","text":"תקציב החינוך יקוצץ"},"relation":"unrelated"}',
111	  ].join('\n'),
112	);
113	
114	test('the protocol over a tiny set: lexical retrieval finds every partner, and its judge sees no contradiction', async () => {
115	  const report = await compare(TINY, { retrievers: [lexicalRetriever()], judges: [lexicalJudge()] });
116	  assert.deepEqual(report.pairs, { count: 4, claims: 4, byRelation: { equivalent: 0, entails: 0, contradicts: 2, 'same-subject': 0, unrelated: 2 } });
117	
118	  const lexical = report.retrieval.lexical;
119	  // Each claim's one partner shares two of three words and is nearest; recall is full at every depth.
120	  assert.deepEqual(lexical.recallAt, { 5: 1, 20: 1, 100: 1 });
121	  assert.equal(lexical.mrr, 1);
122	  assert.equal(lexical.subjectSeparation, 1);
123	  assert.equal(lexical.queries, 4);
124	  assert.deepEqual(lexical.cost, { calls: 0, characters: 0 });
125	
126	  const judged = report.judgment.lexical;
127	  assert.equal(judged.contradictionRecall, 0);
128	  assert.equal(judged.perRelation.unrelated.recall, 1);
129	  assert.match(renderReport(report), /\| lexical \| 100\.0% \| 100\.0% \| 100\.0% \| 1\.000 \| 100\.0% \| 4 \| 0 \| 0 \|/);
130	});
131	
132	test('an embedding retriever is scored through the ingestion port and pays once per claim', async () => {
133	  // A scripted embedder that puts the two train claims on one axis and the two school claims on another.
134	  const embedder: Embedder = {
135	    modelVersion: 'scripted/axes',
136	    async embed(text) {
137	      return [text.includes('רכבת') ? 1 : 0, text.includes('חינוך') ? 1 : 0];
138	    },
139	  };
140	  const retriever = embeddingRetriever(embedder);
141	  const report = await compare(TINY, { retrievers: [retriever], judges: [] });
142	  const result = report.retrieval['embedding:scripted/axes'];
143	  assert.equal(result.recallAt[5], 1);
144	  assert.equal(result.subjectSeparation, 1);
145	  // Four distinct claims, each embedded once however many pairs it appears in.
146	  const characters = claimsOf(TINY).reduce((sum, claim) => sum + claim.text.length, 0);
147	  assert.deepEqual(result.cost, { calls: 4, characters });
148	});
