150	test("the paper's method as a judge: a scripted clause model yields the relation and the trail, and pays per clause pair", async () => {
151	  const model: ClauseModel = {
152	    modelVersion: 'scripted/clauses',
153	    promptVersion: 'decompose-v0',
154	    async decompose(text) {
155	      const negated = text.includes('לא');
156	      return { premises: ['הממשלה התחייבה'], consequences: [negated ? 'הרכבת לא נפתחת' : 'הרכבת נפתחת'] };
157	    },
158	    async relate(p, q) {
159	      if (p === q) return 'entails';
160	      if (p.includes('רכבת') && q.includes('רכבת')) return 'contradicts';
161	      return 'neutral';
162	    },
163	  };
164	  const judge = logicalJudge(model);
165	  const [pair] = TINY;
166	  const verdict = await judge.judge(pair.a, pair.b);
167	  assert.equal(verdict.relation, 'contradicts');
168	  assert.deepEqual(verdict.trail, { premises: [['הממשלה התחייבה', 'הממשלה התחייבה']], consequences: [['הרכבת נפתחת'], ['הרכבת לא נפתחת']] });
169	  // Two decompositions; the identical premises are one judged pair (the reverse direction
170	  // shares the key); the consequences are one judged pair, since a contradiction ends the
171	  // equivalence check and the contradiction scan finds it cached.
172	  assert.equal(judge.cost.calls, 2 + 1 + 1);
173	});
