180	  assert.equal(report.retrieval.lexical.recallAt[100], 1);
181	  // The one-word-apart contradiction (p07) and the wordless paraphrase (p02) are exactly what the baseline cannot see.
182	  assert.equal(report.judgment.lexical.contradictionRecall, 0);
183	  assert.ok(report.judgment.lexical.perRelation.equivalent.recall < 1);
184	  assert.throws(() => resolveMethods(['embedding:bge-m3']), /no adapter for method "embedding:bge-m3"/);
