1	// The syntactic–semantic Jaccard measure of Heldring & Torres (arXiv 2608.15325), as a pure
2	// function over decompositions someone else produced. What a model contributes — the
3	// premises, the conclusion's consequences, the entailment judgments — comes in as
4	// arguments; what this computes is the counting, which is the part the paper's worked
5	// example pins down exactly (docs/architecture/claim-similarity.md §1).
6	//
7	// Two arguments are compared on two Jaccard overlaps: their premise sets and the
8	// consequence sets of their conclusions, each taken modulo the equivalence the judgments
9	// establish. The overlap counts *classes*, which is what the paper's Figures 3 and 4 do
10	// (one premise on one side equivalent to both on the other is one shared class out of
11	// two) — its Definition 20 counts formulas instead and gives a third there; the figures
12	// are what the reported numbers come from, so the figures win.
13	
14	/** Whether two clauses entail each other. Symmetric by definition; called once per pair. */
15	export type Equivalent = (x: string, y: string) => Promise<boolean>;
16	
17	export type Decomposed = {
18	  premises: string[];
19	  /** The conclusion's consequences in CNF — the paper's CN_F(φ) — listed once each. */
20	  consequences: string[];
21	};
22	
23	export type Overlap = {
24	  /** Classes with a member on each side. */
25	  shared: number;
26	  /** Classes in the union. */
27	  distinct: number;
28	  /** The classes themselves, each as the clauses it holds — the trail a reader can check. */
29	  classes: string[][];
30	};
31	
32	export type Similarity = {
33	  similarity: number;
34	  premises: Overlap;
35	  consequences: Overlap;
36	};
37	
38	/**
39	 * Jaccard overlap of two clause lists modulo equivalence. Cross-side pairs are judged, and
40	 * equivalence is closed transitively over what was judged: a clause on the left equivalent
41	 * to two on the right makes all three one class. Two clauses on the same side that are
42	 * equivalent to each other but to nothing opposite stay two classes — the paper takes
43	 * premise sets to be non-redundant, and judging same-side pairs would double the calls to
44	 * find out whether a model's decomposition honoured that.
45	 */
46	export async function classOverlap(left: string[], right: string[], equivalent: Equivalent): Promise<Overlap> {
47	  const items = [...left.map((clause) => ({ clause, side: 'left' as const })), ...right.map((clause) => ({ clause, side: 'right' as const }))];
48	  const parent = items.map((_, index) => index);
49	  const find = (index: number): number => (parent[index] === index ? index : (parent[index] = find(parent[index])));
50	  const union = (a: number, b: number) => {
51	    parent[find(a)] = find(b);
52	  };
53	
54	  for (let i = 0; i < left.length; i++) {
55	    for (let j = 0; j < right.length; j++) {
56	      if (await equivalent(left[i], right[j])) union(i, left.length + j);
57	    }
58	  }
59	
60	  const byRoot = new Map<number, { clauses: string[]; sides: Set<'left' | 'right'> }>();
61	  items.forEach((item, index) => {
62	    const root = find(index);
63	    const group = byRoot.get(root) ?? { clauses: [], sides: new Set() };
64	    group.clauses.push(item.clause);
65	    group.sides.add(item.side);
66	    byRoot.set(root, group);
67	  });
68	  const groups = [...byRoot.values()];
69	  return {
70	    shared: groups.filter((group) => group.sides.size === 2).length,
71	    distinct: groups.length,
72	    classes: groups.map((group) => group.clauses),
73	  };
74	}
75	
76	/** The paper's convention: two empty sets are maximally similar, one empty set is not. */
77	const ratio = (overlap: Overlap, left: number, right: number): number => {
78	  if (left === 0 && right === 0) return 1;
79	  if (left === 0 || right === 0) return 0;
80	  return overlap.shared / overlap.distinct;
81	};
82	
83	/**
84	 * sim^σ(a, b) = σ · s_syn + (1 − σ) · s_sem, for 0 < σ < 1. One is returned exactly when
85	 * every class is shared on both sides — the paper's Theorem 1, argument equivalence.
86	 */
87	export async function syntacticSemanticJaccard(
88	  a: Decomposed,
89	  b: Decomposed,
90	  equivalent: Equivalent,
91	  sigma = 0.5,
92	): Promise<Similarity> {
93	  if (!(sigma > 0 && sigma < 1)) throw new Error(`sigma must lie strictly between 0 and 1, got ${sigma}`);
94	  const premises = await classOverlap(a.premises, b.premises, equivalent);
95	  const consequences = await classOverlap(a.consequences, b.consequences, equivalent);
96	  const syntactic = ratio(premises, a.premises.length, b.premises.length);
97	  const semantic = ratio(consequences, a.consequences.length, b.consequences.length);
98	  return { similarity: sigma * syntactic + (1 - sigma) * semantic, premises, consequences };
99	}
100

