1	// Fetches the committed candidate list and saves what came back, so reconnaissance can
2	// then happen offline against bytes in the repo.
3	//
4	// It exists because the fetching and the reading cannot happen in the same place: agent
5	// sessions are denied these hosts by their egress policy, and a policy boundary is not
6	// something to route around. This runs where that is allowed — the `hitbut/fetch-samples`
7	// task, Action-side — and everything downstream of it reads `dev/samples/payloads/`.
8	//
9	// A candidate that refuses us is an answer, not a failure: the run records the reason,
10	// keeps going, and exits clean. What it will not do is write a refusal to disk as though
11	// it were a document, which is what the shipped fetcher's bot-wall detection is for.
12	//
13	// Usage: `npm run fetch-samples`, or `-- --force` to re-fetch what is already saved,
14	// `-- --only <id>[,<id>]` to work one candidate.
15	import { mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
16	import { fileURLToPath } from 'node:url';
17	import { fetchPage } from '../../src/backend/acquisition/fetcher.ts';
18	
19	type Candidate = {
20	  id: string;
21	  url: string;
22	  group: string;
23	  surface: string;
24	  asks: string;
25	};
26	
27	const SAMPLES = fileURLToPath(new URL('../samples/', import.meta.url));
28	const PAYLOADS = `${SAMPLES}payloads/`;
29	const CANDIDATES = `${SAMPLES}candidates.json`;
30	const REPORT = `${SAMPLES}report.GENERATED.md`;
31	
32	const force = process.argv.includes('--force');
33	const onlyFlag = process.argv.indexOf('--only');
34	const only = onlyFlag === -1 ? null : new Set((process.argv[onlyFlag + 1] ?? '').split(',').filter(Boolean));
35	
36	/**
37	 * The extension is a claim about what came back, so it is read off the bytes rather than
38	 * off what the candidate hoped for — an endpoint that answers with a login page is the
39	 * finding, and naming that file `.json` would hide it.
40	 */
41	function extensionFor(body: string): string {
42	  const head = body.trimStart().slice(0, 400);
43	  if (head.startsWith('{') || head.startsWith('[')) return 'json';
44	  if (/^<\?xml|^<(rss|feed|Edmx|edmx)/i.test(head)) return 'xml';
45	  if (/^<!doctype html|^<html/i.test(head)) return 'html';
46	  return 'txt';
47	}
48	
49	/** Enough of the body to recognise it in the report, on one line. */
50	const preview = (body: string): string =>
51	  body.trimStart().slice(0, 220).replace(/\s+/g, ' ').replace(/\|/g, '\\|');
52	
53	const savedNames = (): string[] => {
54	  mkdirSync(PAYLOADS, { recursive: true });
55	  return readdirSync(PAYLOADS);
56	};
57	
58	type Outcome = {
59	  candidate: Candidate;
60	  state: 'saved' | 'already saved' | 'refused' | 'not fetched';
61	  detail: string;
62	  file: string | null;
63	  bytes: number | null;
64	};
65	
66	const file = readFileSync(CANDIDATES, 'utf8');
67	const candidates: Candidate[] = JSON.parse(file).candidates;
68	if (!Array.isArray(candidates) || candidates.length === 0) {
69	  // The list being unusable is our own breakage, unlike a source refusing us.
70	  throw new Error(`${CANDIDATES} carries no candidates`);
71	}
72	
73	const outcomes: Outcome[] = [];
74	const existing = savedNames();
75	
76	for (const candidate of candidates) {
77	  const already = existing.find((name) => name.startsWith(`${candidate.id}.`));
78	  // The report is a view of the whole list, so a candidate this run did not touch is
79	  // still reported from what is on disk — a `--only` run must not erase the record of
80	  // everything it did not ask about.
81	  if (only && !only.has(candidate.id)) {
82	    outcomes.push({
83	      candidate,
84	      state: already ? 'already saved' : 'not fetched',
85	      detail: 'outside this run’s --only selection',
86	      file: already ?? null,
87	      bytes: already ? readFileSync(`${PAYLOADS}${already}`, 'utf8').length : null,
88	    });
89	    continue;
90	  }
91	  if (already && !force) {
92	    outcomes.push({
93	      candidate,
94	      state: 'already saved',
95	      detail: 'no request was issued — pass --force to re-fetch',
96	      file: already,
97	      bytes: readFileSync(`${PAYLOADS}${already}`, 'utf8').length,
98	    });
99	    console.log(`  [already saved] ${candidate.id}`);
100	    continue;
101	  }
102	
103	  const result = await fetchPage(
104	    candidate.url,
